sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  var leaving_from = api.data.dt_req.result.leaving_from.displayValue;
  var going_to = api.data.dt_req.result.going_to.displayValue;
  var trip_type = api.data.dt_req.result.trip_type.displayValue;
  var cabin = api.data.dt_req.result.cabin_class.displayValue;

  return [
  {
    "label": "Leaving from",
    "value": {
      "type": "string",
      "value": leaving_from
    }
  },
  {
    "label": "Going to",
    "value": {
      "type": "string",
      "value": going_to
    }
  },
  {
    "label": "Trip type",
    "value": {
      "type": "string",
      "value": trip_type
    }
  },
  {
    "label": "Cabin class",
    "value": {
      "type": "string",
      "value": cabin
    }
  }];
}
